export interface Product {
  id: string;
  name: string;
  imageId: string | null;
  comment: string | null;
}
export type CreateProductData = Omit<Product, 'id'>;

export interface Item {
  id: string;
  product: Product;
  count: number;
  groupColor: string | null;
  status: ItemStatus;
}

export enum ItemStatus {
  ToBuy = 'to_buy',
  Bought = 'bought'
}

export type CreateItemData = Omit<Item, 'id' | 'product'> & { product: CreateProductData };
export type UpdateItemData = Partial<Omit<CreateItemData, 'product'>>;

export interface List {
  id: string;
  name: string;
  comment: string | null;
  imageId: string | null;
  items: Item[];
}

export type CreateListData = Omit<List, 'id' | 'items'>;
export type UpdateListData = CreateListData;
